interface Schedule {
  days: string[];
  startTime: string;
  endTime: string;
}
interface BatchRow {
  id: string;
  name: string;
  code: string;
  /** The academy's own batch ID — SFCMC001005, generated and permanent. */
  batchId: string | null;
  batchNo: number;
  sequence: number;
  status: string;
  courseId: string;
  courseTitle: string;
  instructorId: string | null;
  instructorName: string | null;
  associates: { id: string; name: string }[];
  capacity: number | null;
  enrolledCount: number;
  startDate: string | null;
  endDate: string | null;
  /** When the office created it — what "recently created" sorts on. */
  createdAt: string;
  schedule: Schedule | null;
}
interface Stats {
  total: number;
  upcoming: number;
  ongoing: number;
  completed: number;
  learners: number;
}
interface Query {
  page: number;
  pageSize: number;
  search?: string;
  status?: string;
  courseId?: string;
  createdFrom?: string;
  createdTo?: string;
  timeFrom?: string;
  timeTo?: string;
  sort?: string;
}

/** The class-time windows the academy actually thinks in. */
const TIME_SLOTS: { value: string; label: string; from: string; to: string }[] =
  [
    {
      value: "morning",
      label: "Morning (before 12)",
      from: "00:00",
      to: "11:59",
    },
    {
      value: "afternoon",
      label: "Afternoon (12 – 5)",
      from: "12:00",
      to: "16:59",
    },
    {
      value: "evening",
      label: "Evening (after 5)",
      from: "17:00",
      to: "23:59",
    },
  ];

const SORTS: { value: string; label: string }[] = [
  { value: "sequence", label: "Academy order" },
  { value: "recent", label: "Recently created" },
  { value: "starting", label: "Starting soonest" },
  { value: "name", label: "Name A–Z" },
];
interface Opt {
  id: string;
  title?: string;
  name?: string;
}

const STATUS_BADGE: Record<string, string> = {
  UPCOMING: "bg-sky-100 text-sky-700 dark:bg-sky-500/15 dark:text-sky-300",
  ONGOING:
    "bg-emerald-100 text-emerald-700 dark:bg-emerald-500/15 dark:text-emerald-300",
  COMPLETED: "bg-muted text-muted-foreground",
  CANCELLED: "bg-rose-100 text-rose-700 dark:bg-rose-500/15 dark:text-rose-300",
};
const ALL = "all";
const NONE = "none";

interface FormState {
  name: string;
  code: string;
  /** Read-only — shown so the office can quote it; never edited here. */
  batchId: string | null;
  sequence: string;
  courseId: string;
  instructorId: string;
  status: string;
  capacity: string;
  startDate: string;
  endDate: string;
  days: string[];
  startTime: string;
  endTime: string;
  associateIds: string[];
}
const EMPTY: FormState = {
  name: "",
  code: "",
  batchId: null,
  sequence: "",
  courseId: "",
  instructorId: "",
  status: "UPCOMING",
  capacity: "",
  startDate: "",
  endDate: "",
  days: [],
  startTime: "",
  endTime: "",
  associateIds: [],
};

function fromBatch(b: BatchRow): FormState {
  return {
    name: b.name,
    code: b.code,
    batchId: b.batchId,
    sequence: b.sequence ? String(b.sequence) : "",
    courseId: b.courseId,
    instructorId: b.instructorId ?? "",
    status: b.status,
    capacity: b.capacity != null ? String(b.capacity) : "",
    startDate: b.startDate ? b.startDate.slice(0, 10) : "",
    endDate: b.endDate ? b.endDate.slice(0, 10) : "",
    days: b.schedule?.days ?? [],
    startTime: b.schedule?.startTime ?? "",
    endTime: b.schedule?.endTime ?? "",
    associateIds: b.associates.map((a) => a.id),
  };
}

/** "Rahul Verma + 2 associates" — the lead, and how many co-teach with them. */
function teachersLabel(b: BatchRow): string {
  const extra = b.associates.length;
  if (!b.instructorName && !extra) return "";
  const more = extra ? `${extra} associate${extra === 1 ? "" : "s"}` : "";
  return b.instructorName
    ? [b.instructorName, more].filter(Boolean).join(" + ")
    : more;
}

/**
 * Associate instructors live in their own table and have their own endpoints,
 * so the form saves the batch first and then brings its associates in line.
 * A failure here leaves the batch saved and says so.
 */
async function syncAssociates(
  batchId: string,
  before: string[],
  after: string[],
) {
  const added = after.filter((id) => !before.includes(id));
  const removed = before.filter((id) => !after.includes(id));
  if (added.length) {
    await api.post(`/api/batches/${batchId}/associates`, { userIds: added });
  }
  for (const id of removed) {
    await api.del(`/api/batches/${batchId}/associates/${id}`);
  }
}

function fmtDate(iso: string | null): string {
  return iso ? format(new Date(iso), "d MMM yyyy") : "";
}

export function BatchesClient({
  batches,
  total,
  query,
  stats,
  courses,
  instructors,
  associateOptions = [],
  viewerId,
}: {
  batches: BatchRow[];
  total: number;
  query: Query;
  stats: Stats;
  courses: Opt[];
  instructors: Opt[];
  /** Instructors who can co-teach a batch, for the associate picker. */
  associateOptions?: Opt[];
  /**
   * Set on the instructor panel. Batches this person only assists on are
   * listed too, but only the lead (or staff) may edit them.
   */
  viewerId?: string;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const [search, setSearch] = useState(query.search ?? "");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState<BatchRow | null>(null);
  const [form, setForm] = useState<FormState>(EMPTY);
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState<BatchRow | null>(null);
  const [detailId, setDetailId] = useState<string | null>(null);
  const [managing, setManaging] = useState<BatchStudentsTarget | null>(null);

  function manageStudents(b: BatchRow) {
    setManaging({ id: b.id, name: b.name, capacity: b.capacity });
  }

  /** An associate on the instructor panel: may open the batch, not edit it. */
  const assistsOnly = (b: BatchRow) =>
    Boolean(viewerId && b.instructorId !== viewerId);
  const profileHref = (b: BatchRow) => `${pathname.replace(/\/$/, "")}/${b.id}`;

  const totalPages = Math.max(1, Math.ceil(total / query.pageSize));
  const hasFilters = Boolean(
    query.search ||
    query.status ||
    query.courseId ||
    query.createdFrom ||
    query.createdTo ||
    query.timeFrom ||
    query.timeTo ||
    (query.sort && query.sort !== "sequence"),
  );
  /** Which preset the current time window matches, if any. */
  const slot =
    TIME_SLOTS.find((s) => s.from === query.timeFrom && s.to === query.timeTo)
      ?.value ?? (query.timeFrom || query.timeTo ? "custom" : ALL);

  const batchesExportHref = (() => {
    const p = new URLSearchParams();
    if (query.search) p.set("search", query.search);
    if (query.status) p.set("status", query.status);
    if (query.courseId) p.set("course", query.courseId);
    if (query.createdFrom) p.set("createdFrom", query.createdFrom);
    if (query.createdTo) p.set("createdTo", query.createdTo);
    if (query.timeFrom) p.set("timeFrom", query.timeFrom);
    if (query.timeTo) p.set("timeTo", query.timeTo);
    if (query.sort && query.sort !== "sequence") p.set("sort", query.sort);
    const qs = p.toString();
    return `/api/batches/export${qs ? `?${qs}` : ""}`;
  })();

  const setParams = useCallback(
    (next: Record<string, string | number | undefined>) => {
      const merged = {
        search: query.search,
        status: query.status,
        course: query.courseId,
        createdFrom: query.createdFrom,
        createdTo: query.createdTo,
        timeFrom: query.timeFrom,
        timeTo: query.timeTo,
        sort: query.sort,
        page: query.page,
        ...next,
      };
      const p = new URLSearchParams();
      if (merged.search) p.set("search", String(merged.search));
      if (merged.status) p.set("status", String(merged.status));
      if (merged.course) p.set("course", String(merged.course));
      if (merged.createdFrom) p.set("createdFrom", String(merged.createdFrom));
      if (merged.createdTo) p.set("createdTo", String(merged.createdTo));
      if (merged.timeFrom) p.set("timeFrom", String(merged.timeFrom));
      if (merged.timeTo) p.set("timeTo", String(merged.timeTo));
      if (merged.sort && merged.sort !== "sequence")
        p.set("sort", String(merged.sort));
      if (merged.page && Number(merged.page) > 1)
        p.set("page", String(merged.page));
      const qs = p.toString();
      router.push(qs ? `${pathname}?${qs}` : pathname);
    },
    [router, pathname, query],
  );

  function clearFilters() {
    setSearch("");
    setParams({
      search: undefined,
      status: undefined,
      course: undefined,
      createdFrom: undefined,
      createdTo: undefined,
      timeFrom: undefined,
      timeTo: undefined,
      sort: undefined,
      page: 1,
    });
  }

  /** Pick a class-time window, or clear it. */
  function setSlot(value: string) {
    const preset = TIME_SLOTS.find((s) => s.value === value);
    setParams({
      timeFrom: preset?.from,
      timeTo: preset?.to,
      page: 1,
    });
  }

  function set<K extends keyof FormState>(key: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [key]: value }));
  }
  function toggleDay(day: string) {
    setForm((prev) => ({
      ...prev,
      days: prev.days.includes(day)
        ? prev.days.filter((d) => d !== day)
        : [...prev.days, day],
    }));
  }

  function openCreate() {
    setEditing(null);
    setForm(EMPTY);
    setDialogOpen(true);
  }
  function openEdit(b: BatchRow) {
    setEditing(b);
    setForm(fromBatch(b));
    setDialogOpen(true);
  }

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setSaving(true);
    const payload = {
      name: form.name,
      code: form.code || undefined,
      sequence: form.sequence ? Number(form.sequence) : undefined,
      courseId: form.courseId,
      instructorId: form.instructorId || undefined,
      status: form.status,
      capacity: form.capacity ? Number(form.capacity) : undefined,
      startDate: form.startDate || undefined,
      endDate: form.endDate || undefined,
      schedule: {
        days: form.days,
        startTime: form.startTime,
        endTime: form.endTime,
      },
    };
    try {
      let batchId: string;
      if (editing) {
        await api.patch(`/api/batches/${editing.id}`, payload);
        batchId = editing.id;
      } else {
        batchId = (await api.post<{ id: string }>("/api/batches", payload)).id;
      }
      const lead = editing || !viewerId ? form.instructorId : viewerId;
      try {
        await syncAssociates(
          batchId,
          editing?.associates.map((a) => a.id) ?? [],
          form.associateIds.filter((id) => id !== lead),
        );
        toast.success(editing ? "Batch updated." : "Batch created.");
      } catch (err) {
        toast.warning(
          `Batch saved, but the associate instructors weren't: ${err instanceof ApiError ? err.message : "try again from the batch profile."}`,
        );
      }
      setDialogOpen(false);
      router.refresh();
    } catch (err) {
      if (err instanceof ApiError) {
        const d = err.details as { issues?: { message: string }[] } | undefined;
        toast.error(d?.issues?.[0]?.message ?? err.message);
      } else toast.error("Save failed.");
    } finally {
      setSaving(false);
    }
  }

  async function confirmDelete() {
    if (!deleting) return;
    try {
      await api.del(`/api/batches/${deleting.id}`);
      toast.success("Batch deleted.");
      setDeleting(null);
      router.refresh();
    } catch (err) {
      toast.error(err instanceof ApiError ? err.message : "Delete failed.");
    }
  }

  const statCards = [
    {
      label: "Total batches",
      value: stats.total,
      icon: Layers,
      tone: "text-rose-500",
    },
    {
      label: "Upcoming",
      value: stats.upcoming,
      icon: CalendarClock,
      tone: "text-sky-500",
    },
    {
      label: "Ongoing",
      value: stats.ongoing,
      icon: Radio,
      tone: "text-emerald-500",
    },
    {
      label: "Learners",
      value: stats.learners,
      icon: Users,
      tone: "text-violet-500",
    },
  ];

  const columns: Column<BatchRow>[] = [
    {
      key: "name",
      header: "Batch",
      cell: (b) => (
        <div className="min-w-0">
          <Link
            href={profileHref(b)}
            className="block truncate font-medium hover:underline"
          >
            {b.name}
          </Link>
          <p className="text-muted-foreground truncate text-xs">
            {b.batchId ? (
              <span className="text-foreground font-medium tabular-nums">
                {b.batchId}
              </span>
            ) : (
              b.code
            )}
            {teachersLabel(b) ? ` · ${teachersLabel(b)}` : ""}
            {assistsOnly(b) ? " · you assist" : ""}
          </p>
        </div>
      ),
    },
    {
      key: "course",
      header: "Course",
      cell: (b) => (
        <span className="text-muted-foreground line-clamp-2 text-sm">
          {b.courseTitle}
        </span>
      ),
    },
    {
      key: "schedule",
      header: "Schedule",
      cell: (b) =>
        b.schedule && (b.schedule.days.length || b.schedule.startTime) ? (
          <div className="text-sm">
            <p>{b.schedule.days.join(", ") || "—"}</p>
            {b.schedule.startTime && (
              <p className="text-muted-foreground text-xs">
                {b.schedule.startTime}
                {b.schedule.endTime ? `–${b.schedule.endTime}` : ""}
              </p>
            )}
          </div>
        ) : (
          <span className="text-muted-foreground text-sm">—</span>
        ),
    },
    {
      key: "dates",
      header: "Dates",
      cell: (b) => (
        <div className="text-sm whitespace-nowrap">
          {b.startDate || b.endDate ? (
            <p>
              {fmtDate(b.startDate) || "—"}
              {b.endDate ? ` – ${fmtDate(b.endDate)}` : ""}
            </p>
          ) : (
            <p className="text-muted-foreground">—</p>
          )}
          {/* When it was set up, so "recently created" can be seen as well as
              sorted on. */}
          <p className="text-muted-foreground text-xs">
            Created {fmtDate(b.createdAt)}
          </p>
        </div>
      ),
    },
    {
      key: "seats",
      header: "Seats",
      cell: (b) => {
        const cap = b.capacity ?? 0;
        const pct = cap
          ? Math.min(100, Math.round((b.enrolledCount / cap) * 100))
          : 0;
        return (
          <div className="w-24">
            <p className="text-sm tabular-nums">
              {b.enrolledCount}
              <span className="text-muted-foreground">
                {cap ? ` / ${cap}` : ""}
              </span>
            </p>
            {cap > 0 && (
              <div className="bg-muted mt-1 h-1.5 overflow-hidden rounded-full">
                <div
                  className={cn(
                    "h-full rounded-full",
                    pct >= 100 ? "bg-rose-500" : "bg-primary",
                  )}
                  style={{ width: `${pct}%` }}
                />
              </div>
            )}
          </div>
        );
      },
    },
    {
      key: "status",
      header: "Status",
      cell: (b) => (
        <Badge variant="secondary" className={STATUS_BADGE[b.status]}>
          {BATCH_STATUS_LABEL[b.status] ?? b.status}
        </Badge>
      ),
    },
    {
      key: "actions",
      header: <span className="sr-only">Actions</span>,
      headerClassName: "w-10",
      cell: (b) => rowActions(b),
    },
  ];

  function rowActions(b: BatchRow) {
    return (
      <DropdownMenu>
        <DropdownMenuTrigger
          render={<Button variant="ghost" size="icon-sm" />}
          aria-label="Actions"
        >
          <MoreHorizontal className="size-4" />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem onClick={() => router.push(profileHref(b))}>
            <ArrowUpRight className="size-4" /> Open batch profile
          </DropdownMenuItem>
          {!assistsOnly(b) && (
            <>
              <DropdownMenuItem onClick={() => setDetailId(b.id)}>
                <Eye className="size-4" /> View details
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => openEdit(b)}>
                <Pencil className="size-4" /> Edit
              </DropdownMenuItem>
              <DropdownMenuItem onClick={() => manageStudents(b)}>
                <UserPlus className="size-4" /> Manage students
              </DropdownMenuItem>
              <DropdownMenuItem
                className="text-destructive focus:text-destructive"
                onClick={() => setDeleting(b)}
              >
                <Trash2 className="size-4" /> Delete
              </DropdownMenuItem>
            </>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    );
  }

  function renderBatchCard(b: BatchRow) {
    const cap = b.capacity ?? 0;
    const pct = cap
      ? Math.min(100, Math.round((b.enrolledCount / cap) * 100))
      : 0;
    return (
      <div className="rounded-xl border p-4">
        <div className="flex items-start justify-between gap-2">
          <Link href={profileHref(b)} className="min-w-0 flex-1 text-left">
            <p className="truncate font-medium">{b.name}</p>
            <p className="text-muted-foreground truncate text-xs">
              {b.batchId ? (
                <span className="text-foreground font-medium tabular-nums">
                  {b.batchId}
                </span>
              ) : (
                b.code
              )}
              {teachersLabel(b) ? ` · ${teachersLabel(b)}` : ""}
              {assistsOnly(b) ? " · you assist" : ""}
            </p>
          </Link>
          <div className="flex shrink-0 items-center gap-1">
            <Badge variant="secondary" className={STATUS_BADGE[b.status]}>
              {BATCH_STATUS_LABEL[b.status] ?? b.status}
            </Badge>
            {rowActions(b)}
          </div>
        </div>

        <p className="text-muted-foreground mt-2 truncate text-sm">
          {b.courseTitle}
        </p>

        <div className="text-muted-foreground mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs">
          {b.schedule && (b.schedule.days.length || b.schedule.startTime) ? (
            <span className="flex items-center gap-1">
              <CalendarClock className="size-3.5" />
              {b.schedule.days.join(", ") || "—"}
              {b.schedule.startTime ? ` · ${b.schedule.startTime}` : ""}
            </span>
          ) : null}
          {(b.startDate || b.endDate) && (
            <span className="flex items-center gap-1">
              <CalendarDays className="size-3.5" />
              {fmtDate(b.startDate) || "—"}
              {b.endDate ? ` – ${fmtDate(b.endDate)}` : ""}
            </span>
          )}
          <span className="flex items-center gap-1">Created {fmtDate(b.createdAt)}</span>
        </div>

        <div className="mt-3 flex items-center gap-3">
          <span className="text-sm tabular-nums">
            {b.enrolledCount}
            <span className="text-muted-foreground">
              {cap ? ` / ${cap}` : ""}
            </span>
          </span>
          {cap > 0 && (
            <div className="bg-muted h-1.5 flex-1 overflow-hidden rounded-full">
              <div
                className={cn(
                  "h-full rounded-full",
                  pct >= 100 ? "bg-rose-500" : "bg-primary",
                )}
                style={{ width: `${pct}%` }}
              />
            </div>
          )}
        </div>
      </div>
    );
  }

  const canSave = form.name.trim().length >= 3 && Boolean(form.courseId);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Batches"
        description="Schedule and manage course cohorts, their timings and capacity."
        actions={
          <div className="flex gap-2">
            <Button
              variant="outline"
              nativeButton={false}
              render={<a href={batchesExportHref} />}
            >
              <Download className="size-4" /> Export
            </Button>
            <Button onClick={openCreate}>
              <Plus className="size-4" /> New batch
            </Button>
          </div>
        }
      />

      {/* Summary */}
      <div className="grid grid-cols-2 gap-3 sm:gap-4 lg:grid-cols-4">
        {statCards.map((s) => (
          <Card key={s.label}>
            <CardContent className="flex items-center gap-3 py-4">
              <div className="bg-muted grid size-10 shrink-0 place-items-center rounded-lg">
                <s.icon className={`size-5 ${s.tone}`} />
              </div>
              <div className="min-w-0">
                <p className="text-2xl leading-none font-semibold tabular-nums">
                  {s.value.toLocaleString("en-IN")}
                </p>
                <p className="text-muted-foreground mt-1 truncate text-xs">
                  {s.label}
                </p>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <DataTable
        columns={columns}
        data={batches}
        rowKey={(b) => b.id}
        renderCard={renderBatchCard}
        emptyIcon={CalendarDays}
        emptyTitle={hasFilters ? "No matching batches" : "No batches yet"}
        emptyDescription={
          hasFilters
            ? "Try adjusting your search or filters."
            : "Create your first batch to get started."
        }
        toolbar={
          <div className="flex flex-col gap-3">
            <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  setParams({ search: search || undefined, page: 1 });
                }}
                className="flex-1 sm:max-w-xs"
              >
                <Input
                  placeholder="Search batches…"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
              </form>
              <div className="flex gap-2">
                <Select
                  value={query.status ?? ALL}
                  onValueChange={(v) =>
                    setParams({
                      status: !v || v === ALL ? undefined : v,
                      page: 1,
                    })
                  }
                >
                  <SelectTrigger className="flex-1 sm:w-40">
                    <SelectValue>
                      {(v) =>
                        !v || v === ALL
                          ? "All statuses"
                          : BATCH_STATUS_LABEL[String(v)]
                      }
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={ALL}>All statuses</SelectItem>
                    {BATCH_STATUSES.map((s) => (
                      <SelectItem key={s} value={s}>
                        {BATCH_STATUS_LABEL[s]}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Select
                  value={query.courseId ?? ALL}
                  onValueChange={(v) =>
                    setParams({
                      course: !v || v === ALL ? undefined : v,
                      page: 1,
                    })
                  }
                >
                  <SelectTrigger className="flex-1 sm:w-48">
                    <SelectValue>
                      {(v) =>
                        !v || v === ALL
                          ? "All courses"
                          : (courses.find((c) => c.id === v)?.title ?? "Course")
                      }
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={ALL}>All courses</SelectItem>
                    {courses.map((c) => (
                      <SelectItem key={c.id} value={c.id}>
                        {c.title}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {/* When a class runs — read off the batch's own timetable. */}
                <Select value={slot} onValueChange={(v) => setSlot(String(v))}>
                  <SelectTrigger className="flex-1 sm:w-44">
                    <SelectValue>
                      {(v) =>
                        !v || v === ALL
                          ? "Any class time"
                          : v === "custom"
                            ? `${query.timeFrom ?? "…"} – ${query.timeTo ?? "…"}`
                            : (TIME_SLOTS.find((s) => s.value === v)?.label ??
                              "Any class time")
                      }
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={ALL}>Any class time</SelectItem>
                    {TIME_SLOTS.map((s) => (
                      <SelectItem key={s.value} value={s.value}>
                        {s.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Select
                  value={query.sort ?? "sequence"}
                  onValueChange={(v) =>
                    setParams({ sort: String(v || "sequence"), page: 1 })
                  }
                >
                  <SelectTrigger className="flex-1 sm:w-44">
                    <SelectValue>
                      {(v) =>
                        SORTS.find((s) => s.value === (v ?? "sequence"))
                          ?.label ?? "Academy order"
                      }
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    {SORTS.map((s) => (
                      <SelectItem key={s.value} value={s.value}>
                        {s.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {hasFilters && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={clearFilters}
                    className="text-muted-foreground"
                  >
                    <X className="size-4" /> Clear
                  </Button>
                )}
              </div>
            </div>

            {/* Created between two dates, and an exact class-time window for
                when the three presets aren't the cut the office wants. */}
            <div className="flex flex-wrap items-end gap-3">
              <div className="space-y-1">
                <Label
                  htmlFor="b-created-from"
                  className="text-muted-foreground text-xs"
                >
                  Created from
                </Label>
                <Input
                  id="b-created-from"
                  type="date"
                  className="w-40"
                  value={query.createdFrom ?? ""}
                  onChange={(e) =>
                    setParams({
                      createdFrom: e.target.value || undefined,
                      page: 1,
                    })
                  }
                />
              </div>
              <div className="space-y-1">
                <Label
                  htmlFor="b-created-to"
                  className="text-muted-foreground text-xs"
                >
                  Created to
                </Label>
                <Input
                  id="b-created-to"
                  type="date"
                  className="w-40"
                  value={query.createdTo ?? ""}
                  onChange={(e) =>
                    setParams({
                      createdTo: e.target.value || undefined,
                      page: 1,
                    })
                  }
                />
              </div>
              <div className="space-y-1">
                <Label
                  htmlFor="b-time-from"
                  className="text-muted-foreground text-xs"
                >
                  Class starts after
                </Label>
                <Input
                  id="b-time-from"
                  type="time"
                  className="w-32"
                  value={query.timeFrom ?? ""}
                  onChange={(e) =>
                    setParams({
                      timeFrom: e.target.value || undefined,
                      page: 1,
                    })
                  }
                />
              </div>
              <div className="space-y-1">
                <Label
                  htmlFor="b-time-to"
                  className="text-muted-foreground text-xs"
                >
                  and before
                </Label>
                <Input
                  id="b-time-to"
                  type="time"
                  className="w-32"
                  value={query.timeTo ?? ""}
                  onChange={(e) =>
                    setParams({ timeTo: e.target.value || undefined, page: 1 })
                  }
                />
              </div>
            </div>
          </div>
        }
        footer={
          <div className="flex items-center justify-between">
            <p className="text-muted-foreground text-sm">
              {total} {total === 1 ? "batch" : "batches"}
            </p>
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={query.page <= 1}
                onClick={() => setParams({ page: query.page - 1 })}
              >
                Previous
              </Button>
              <span className="text-muted-foreground text-sm">
                Page {query.page} of {totalPages}
              </span>
              <Button
                variant="outline"
                size="sm"
                disabled={query.page >= totalPages}
                onClick={() => setParams({ page: query.page + 1 })}
              >
                Next
              </Button>
            </div>
          </div>
        }
      />

      {/* Create / edit dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>{editing ? "Edit batch" : "New batch"}</DialogTitle>
            <DialogDescription>
              {editing
                ? "Update this cohort's details."
                : "Set up a new cohort for a course."}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={onSubmit} className="space-y-4">
            <div className="space-y-1.5">
              <Label htmlFor="b-name">Batch name</Label>
              <Input
                id="b-name"
                value={form.name}
                onChange={(e) => set("name", e.target.value)}
                placeholder="e.g. Data Science — Aug 2026 (Weekend)"
              />
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1.5">
                <Label>Course</Label>
                <Select
                  value={form.courseId}
                  onValueChange={(v) => v && set("courseId", v)}
                >
                  <SelectTrigger className="w-full">
                    <SelectValue placeholder="Choose a course">
                      {(v) =>
                        courses.find((c) => c.id === v)?.title ??
                        "Choose a course"
                      }
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    {courses.map((c) => (
                      <SelectItem key={c.id} value={c.id}>
                        {c.title}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label>Instructor</Label>
                <Select
                  value={form.instructorId || NONE}
                  onValueChange={(v) =>
                    set("instructorId", v === NONE ? "" : (v ?? ""))
                  }
                >
                  <SelectTrigger className="w-full">
                    <SelectValue>
                      {(v) =>
                        !v || v === NONE
                          ? "Unassigned"
                          : (instructors.find((i) => i.id === v)?.name ??
                            "Unassigned")
                      }
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={NONE}>Unassigned</SelectItem>
                    {instructors.map((i) => (
                      <SelectItem key={i.id} value={i.id}>
                        {i.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            {associateOptions.length > 0 && (
              <AssociatesField
                options={associateOptions.filter(
                  (o) =>
                    o.id !==
                    (form.instructorId || (!editing ? viewerId : undefined)),
                )}
                value={form.associateIds}
                onChange={(ids) => set("associateIds", ids)}
              />
            )}

            <div className="grid gap-4 sm:grid-cols-3">
              <div className="space-y-1.5">
                <Label>Status</Label>
                <Select
                  value={form.status}
                  onValueChange={(v) => v && set("status", v)}
                >
                  <SelectTrigger className="w-full">
                    <SelectValue>
                      {(v) => BATCH_STATUS_LABEL[String(v)]}
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    {BATCH_STATUSES.map((s) => (
                      <SelectItem key={s} value={s}>
                        {BATCH_STATUS_LABEL[s]}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="b-cap">Capacity</Label>
                <Input
                  id="b-cap"
                  type="number"
                  min={1}
                  value={form.capacity}
                  onChange={(e) => set("capacity", e.target.value)}
                  placeholder="e.g. 50"
                />
              </div>
              {/* The academy's own identity for the cohort. Generated from the
                  course — SFC + its abbreviation + its number + this batch's
                  number — and never editable: certificates quote it. */}
              <div className="space-y-1.5">
                <Label htmlFor="b-batch-id">Batch ID</Label>
                <Input
                  id="b-batch-id"
                  value={form.batchId ?? "Generated when you save"}
                  readOnly
                  disabled
                  className="font-medium tabular-nums"
                />
                <p className="text-muted-foreground text-xs">
                  Generated by the academy and fixed — it appears on the
                  certificate.
                </p>
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="b-sequence">Sequence number</Label>
                <Input
                  id="b-sequence"
                  type="number"
                  min={0}
                  value={form.sequence}
                  onChange={(e) => set("sequence", e.target.value)}
                  placeholder="e.g. 1"
                />
                <p className="text-muted-foreground text-xs">
                  Where it sits in your own list. Change it as often as you
                  like.
                </p>
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="b-code">Code</Label>
                <Input
                  id="b-code"
                  value={form.code}
                  onChange={(e) => set("code", e.target.value)}
                  placeholder="auto"
                />
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1.5">
                <Label htmlFor="b-start">Start date</Label>
                <Input
                  id="b-start"
                  type="date"
                  value={form.startDate}
                  onChange={(e) => set("startDate", e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="b-end">End date</Label>
                <Input
                  id="b-end"
                  type="date"
                  value={form.endDate}
                  onChange={(e) => set("endDate", e.target.value)}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Weekly schedule</Label>
              <div className="flex flex-wrap gap-1.5">
                {WEEKDAYS.map((d) => {
                  const on = form.days.includes(d);
                  return (
                    <button
                      key={d}
                      type="button"
                      onClick={() => toggleDay(d)}
                      className={cn(
                        "h-8 w-11 rounded-md border text-xs font-medium transition-colors",
                        on
                          ? "border-primary bg-primary text-primary-foreground"
                          : "border-input text-muted-foreground hover:bg-accent",
                      )}
                    >
                      {d}
                    </button>
                  );
                })}
              </div>
              <div className="flex items-center gap-2">
                <Input
                  type="time"
                  value={form.startTime}
                  onChange={(e) => set("startTime", e.target.value)}
                  className="w-32"
                  aria-label="Start time"
                />
                <span className="text-muted-foreground text-sm">to</span>
                <Input
                  type="time"
                  value={form.endTime}
                  onChange={(e) => set("endTime", e.target.value)}
                  className="w-32"
                  aria-label="End time"
                />
              </div>
            </div>

            <DialogFooter>
              {editing && (
                <Button
                  type="button"
                  variant="outline"
                  className="sm:mr-auto"
                  onClick={() => {
                    const b = editing;
                    setDialogOpen(false);
                    manageStudents(b);
                  }}
                >
                  <UserPlus className="size-4" /> Manage students
                </Button>
              )}
              <Button
                type="button"
                variant="outline"
                onClick={() => setDialogOpen(false)}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={!canSave || saving}>
                {saving && <Loader2 className="size-4 animate-spin" />}
                {editing ? "Save changes" : "Create batch"}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <BatchDetailSheet
        batchId={detailId}
        onOpenChange={(o) => !o && setDetailId(null)}
      />

      <BatchStudentsSheet
        batch={managing}
        onOpenChange={(o) => !o && setManaging(null)}
      />

      <AlertDialog
        open={!!deleting}
        onOpenChange={(o) => !o && setDeleting(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete “{deleting?.name}”?</AlertDialogTitle>
            <AlertDialogDescription>
              This permanently removes the batch. Batches with enrolled learners
              can&apos;t be deleted.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              className="bg-destructive hover:bg-destructive/90 text-white"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/**
 * Pick any number of associate instructors: chosen ones show as removable
 * chips, and the select below adds another.
 */
function AssociatesField({
  options,
  value,
  onChange,
}: {
  options: Opt[];
  value: string[];
  onChange: (ids: string[]) => void;
}) {
  const nameOf = (id: string) =>
    options.find((o) => o.id === id)?.name ?? "Instructor";
  const remaining = options.filter((o) => !value.includes(o.id));
  const shown = value.filter((id) => options.some((o) => o.id === id));

  return (
    <div className="space-y-1.5">
      <Label>Associate instructors</Label>
      {shown.length > 0 && (
        <div className="flex flex-wrap gap-1.5">
          {shown.map((id) => (
            <span
              key={id}
              className="bg-muted inline-flex items-center gap-1 rounded-md py-0.5 pr-1 pl-2 text-xs"
            >
              {nameOf(id)}
              <button
                type="button"
                aria-label={`Remove ${nameOf(id)}`}
                className="hover:bg-background rounded p-0.5"
                onClick={() => onChange(value.filter((v) => v !== id))}
              >
                <X className="size-3" />
              </button>
            </span>
          ))}
        </div>
      )}
      <Select
        value={NONE}
        onValueChange={(v) => {
          if (v && v !== NONE && !value.includes(String(v)))
            onChange([...value, String(v)]);
        }}
      >
        <SelectTrigger className="w-full" disabled={remaining.length === 0}>
          <SelectValue>
            {() =>
              remaining.length
                ? "Add an associate instructor…"
                : "No more instructors to add"
            }
          </SelectValue>
        </SelectTrigger>
        <SelectContent>
          <SelectItem value={NONE} className="hidden">
            Add an associate instructor…
          </SelectItem>
          {remaining.map((o) => (
            <SelectItem key={o.id} value={o.id}>
              {o.name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <p className="text-muted-foreground text-xs">
        They co-teach the batch and see it under their own batches.
      </p>
    </div>
  );
}
